/* @lc app=leetcode id=1970 lang=kotlin */ class Solution { fun ok(row: Int, col: Int, cells: Array<IntArray>, d: Int): Boolean = Array(row) { BooleanArray(col) }.also { w -> cells.take(d).forEach { (r, c) -> w[r - 1][c - 1] = true } }.let { w -> HashSet<Int>().let { seen -> generateSequence((0 until col).filter { !w[0][it] }.onEach { seen.add(it) }) { f -> f.flatMap { p -> listOf(p / col + 1 to p % col, p / col - 1 to p % col, p / col to p % col + 1, p / col to p % col - 1) }.filter { (r, c) -> r in 0 until row && c in 0 until col && !w[r][c] }.map { (r, c) -> r * col + c }.filter { seen.add(it) }.takeIf { it.isNotEmpty() } }.flatten().any { it / col == row - 1 } } } fun latestDayToCross(row: Int, col: Int, cells: Array<IntArray>): Int = generateSequence(0 to cells.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi + 1) / 2).let { m -> if (ok(row, col, cells, m)) m to hi else lo to m - 1 } }.last().first }